// Flatten one run into a single spreadsheet row. The score fields come from the
// service; the rewrite text is optional and only present on the low-score branch.
const form = $('Resume Upload Form').first().json;
const scored = $('Score Resume').first().json;

let rewrites = '';
for (const item of $input.all()) {
  const blocks = item.json.content;
  if (Array.isArray(blocks)) {
    rewrites = blocks.map(b => b.text || '').join('');
  }
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    company: form.Company || '',
    role: form.Role || '',
    resume: scored.resume,
    score: scored.score,
    max_score: scored.max_score,
    percent: scored.percent,
    keyword_percent: scored.keywords ? scored.keywords.percent : '',
    failed_checks: scored.checks.filter(c => !c.passed).map(c => c.key).join('; '),
    missing_keywords: scored.keywords ? scored.keywords.missing.slice(0, 15).join('; ') : '',
    rewrites,
  },
}];
